#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    vector<array<int, 6>> d(n);
    for (auto &a : d)
        for (auto &x : a) scanf("%d", &x);

    // Faces na ordem A,B,C,D,E,F -> opostos: A-F, B-D, C-E
    int opp[6] = {5, 3, 4, 1, 2, 0};

    // dp[v] = melhor soma acumulada considerando os primeiros dados processados,
    // com o valor da face superior do dado do topo sendo v (-1 = impossível)
    vector<long long> dp(7, -1);

    // Primeiro dado (base da torre): escolhe qualquer face como inferior
    for (int f = 0; f < 6; f++) {
        int b = d[0][f], t = d[0][opp[f]];
        int best = 0;
        for (int g = 0; g < 6; g++)
            if (g != f && g != opp[f]) best = max(best, d[0][g]);
        if (dp[t] < best) dp[t] = best;
    }

    for (int i = 1; i < n; i++) {
        vector<long long> nd(7, -1);
        for (int f = 0; f < 6; f++) {
            int b = d[i][f], t = d[i][opp[f]];
            if (dp[b] < 0) continue; // base do dado i deve casa com topo anterior
            int best = 0;
            for (int g = 0; g < 6; g++)
                if (g != f && g != opp[f]) best = max(best, d[i][g]);
            long long c = dp[b] + best;
            if (nd[t] < c) nd[t] = c;
        }
        dp = move(nd);
    }

    long long ans = 0;
    for (int v = 1; v <= 6; v++) ans = max(ans, dp[v]);
    printf("%lld\n", ans);
    return 0;
}
